insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys2-potential-around-loop', 'ap_physics_2', 'xy_series', 'Electric potential around a circuit loop', 'Potential around a loop', 'Every rise and drop in one trip round; the net change is zero', 'Potential against position for a single loop: a 12 V rise across the battery, then 8 V and 4 V dropped across the two resistors.', 'A graph of electric potential against position as you travel once around a single circuit loop. Starting at zero, the potential rises by 12 volts at the battery, where the tick is marked, stays flat along the connecting wire, drops by 8 volts across the first resistor, stays flat again, then drops by 4 volts across the second resistor, returning to zero. The trace ends at the same potential it started at, because the net change around a closed loop is zero. Illustrative data.', 'position around the loop', 'electric potential (V)', 'The rises and the drops cancel exactly: +12 − 8 − 4 = 0, which is Kirchhoff''s loop rule.', true, null, '["Horizontal axis", "Vertical axis", "Changes along the graph", "End of loop"]'::jsonb, '{"x_range": [-0.15, 4.0], "y_range": [-2.5, 15.0], "y_ticks": [0, 4, 8, 12], "x_ticks": [[0.6, "battery"], [1.8, "resistor 1"], [3.0, "resistor 2"], [3.8, "end"]], "hlines": [{"y": 0.0, "label": "starting potential"}], "series": [{"kind": "line", "style": "solid", "points": [[0.0, 0.0], [0.6, 0.0], [0.6, 12.0], [1.8, 12.0], [1.8, 4.0], [3.0, 4.0], [3.0, 0.0], [3.8, 0.0]], "marks": [{"x": 0.6, "y": 12.0, "label": "+12 V", "place": "above"}, {"x": 1.8, "y": 4.0, "label": "−8 V", "place": "right"}, {"x": 3.0, "y": 0.0, "label": "−4 V", "place": "below"}]}]}'::jsonb, '{:.0f}', null, 'published', 'cramapple-authored; batch=phys2-,physcmech-,precalc-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-residual-plot', 'ap_precalculus', 'xy_series', 'Residual plot', 'Residual plot', 'Residuals against the independent variable, with no pattern', 'Actual minus predicted, plotted against x: scattered either side of zero with no pattern, which is what justifies the model.', 'A residual plot: ten points showing the residual, the actual value minus the value the model predicts, against the independent variable. A horizontal line marks a residual of zero. The points fall on both sides of that line, close to it, with no curve, no fanning and no trend across the plot. That absence of a pattern is what justifies the model as an appropriate fit. Illustrative data.', 'independent variable', 'residual (actual − predicted)', 'A curve, or a long run of residuals with the same sign, says the model is the wrong shape; a funnel says the spread is not constant. Either is a pattern.', true, null, '["Residual (actual − predicted)", "Zero line", "No pattern"]'::jsonb, '{"x_range": [0, 11], "y_range": [-1.6, 1.6], "y_ticks": [-1, 0, 1], "hlines": [{"y": 0.0, "label": "residual = 0"}], "series": [{"kind": "scatter", "points": [[1, -0.4], [2, 0.7], [3, 0.5], [4, -0.8], [5, -0.3], [6, 0.9], [7, -0.6], [8, 0.2], [9, -0.7], [10, 0.6]]}]}'::jsonb, '{:.0f}', null, 'published', 'cramapple-authored; batch=phys2-,physcmech-,precalc-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys2-mb-qualitative', 'ap_physics_2', 'mb_distribution', 'Maxwell–Boltzmann distribution', 'Maxwell-Boltzmann distribution', 'The shape of the curve is set by the temperature of the gas', 'Atomic energies at two temperatures: the hotter gas is flatter, broader and shifted right.', 'Two Maxwell-Boltzmann curves showing the relative number of atoms at each energy, for the same gas at two temperatures. The hotter sample''s curve has a lower, broader peak shifted to higher energy, while the cooler sample''s is taller and narrower. The whole shape of the curve is set by the temperature, which is the feature this diagram exists to teach. Illustrative data.', 'atomic energy', 'relative number of atoms', 'AP Physics 2 asks for the features of the curve, not its functional form.', true, null, '["Horizontal axis", "Vertical axis", "Curve features"]'::jsonb, '{"x_max": 8.0, "series": [{"label": "cooler gas", "theta": 0.8, "style": "solid"}, {"label": "hotter gas", "theta": 1.6, "style": "dashed"}]}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; batch=phys2-,physcmech-,precalc-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('physcmech-xva-graphs', 'ap_physics_c_mechanics', 'kinematic_panels', 'Reading x(t), v(t) and a(t) together', 'x(t), v(t), a(t)', 'Slope of one graph is the value of the next; area under one is the change in the one above', 'One motion at constant acceleration, shown three ways: slopes read downward, areas read upward.', 'Three stacked graphs of the same motion against a shared time axis. The top panel is position against time, a curve whose tangent is drawn at one instant: the slope of that tangent is the instantaneous velocity. The middle panel is velocity against time, a straight line whose own slope is the constant acceleration, with the area under it between two times shaded, because that area is the displacement over the interval. The bottom panel is acceleration against time, a horizontal line, whose area over an interval is the change in velocity. Illustrative data.', 'time t', '', 'Slopes read downward (x to v to a); areas read upward (a to v to x).', true, null, '["Slope of tangent on x–t graph", "Slope of tangent on v–t graph", "Area under v–t curve", "Area under a–t curve"]'::jsonb, '{"x0": 0.0, "v0": 2.0, "a": 1.5, "t_max": 6.0, "x_label_panel": "x(t)  position", "v_label_panel": "v(t)  velocity", "a_label_panel": "a(t)  acceleration", "annotations": [{"panel": "x", "t": 3.0, "y": 12.75, "label": "slope = v(3)", "tangent": true, "slope": 6.5}, {"panel": "v", "t": 3.0, "y": 6.5, "label": "slope = a", "tangent": true, "slope": 1.5}], "shades": [{"panel": "v", "t0": 2.0, "t1": 4.0, "label": "area = Δx"}, {"panel": "a", "t0": 2.0, "t1": 4.0, "label": "area = Δv"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=phys2-,physcmech-,precalc-figures-2026-10-11', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys2-pv-isotherm-work', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_2' and e.kind = 'diagram'
   and e.title = 'Pressure–volume (PV) diagram' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys2-pv-special-processes', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_2' and e.kind = 'diagram'
   and e.title = 'Pressure–volume (PV) diagram' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys2-potential-around-loop', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
