on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys2-mb-qualitative', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_2' and e.kind = 'diagram'
   and e.title = 'Maxwell–Boltzmann distribution (qualitative)' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'physcmech-xva-graphs', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_c_mechanics' and e.kind = 'diagram'
   and e.title = 'Reading x(t), v(t), a(t) graphs' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('phys2-pv-isotherm-work', 'phys2-pv-special-processes', 'phys2-potential-around-loop', 'precalc-residual-plot', 'phys2-mb-qualitative', 'physcmech-xva-graphs') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('phys2-pv-isotherm-work', 'phys2-pv-special-processes', 'phys2-potential-around-loop', 'precalc-residual-plot', 'phys2-mb-qualitative', 'physcmech-xva-graphs');
  if v_n <> 6 then
    raise exception 'expected 6 figures, found %', v_n;
  end if;
end $$;

commit;
